--region init
function MidFestivalPlayerRankBehaviour:InitHandler()
    ---@type ActivityMidFestivalBossMeRankCell
    self._myRankScr = CfUtils.GetLuaScr(self.MyRanking, "Game.Activity.MidFestival.BossDialog.RewardRank.ActivityMidFestivalBossMeRankCell")

    ---@type ActivityMidFestivalBossComponent
    self._activityMidFestivalBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalBossComponent)
