function MidFestivalPlayerRankBehaviour:InitData()
    self._bossHomeDojo = self._activityMidFestivalBossComponent:GetBossHomeDojo()
    self._rankInfo = self._bossHomeDojo.rankInfo
    self:RefreshUI()
end
