--region private
function MidFestivalPlayerRankBehaviour:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self._rankInfo[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type ActivityMidFestivalBossPlayerRankCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.MidFestival.BossDialog.RewardRank.ActivityMidFestivalBossPlayerRankCell")
    scr:Refresh(cellData, luaIndex)
    return cell
end

function MidFestivalPlayerRankBehaviour:RefreshRankList()
    ---@type MidFestivalBossParameterVo
    local parametersVo = CfUtils.GetCf(AutoIds.IdSetting6104, "MidFestivalBossParameterVo", true)[1]
    local showCount = math.min(checkNumber(parametersVo.num), #self._rankInfo)

    if not self.LoopView.IsListViewInit then
        self.LoopView:InitListView(showCount, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopView, showCount)
    end
end

function MidFestivalPlayerRankBehaviour:RefreshMyRank()
    self._myRankScr:Refresh()
end

function MidFestivalPlayerRankBehaviour:RefreshUI()
    local isEmpty = next(self._rankInfo) == nil

    if isEmpty then
        CfUtils.SetActive(self.EmptyNode, true)
        return
    end

    self:RefreshRankList()
    self:RefreshMyRank()
end
